import hmac
import hashlib
import base64
import json
import time
import os
import secrets
from functools import wraps
from flask import Flask, request, jsonify, g

app = Flask(__name__)
app.config['SECRET_KEY'] = os.environ.get('SECRET_KEY', secrets.token_hex(32))

# Simulated database
USERS_DB = {}
SESSIONS_DB = {}
DOCUMENTS_DB = {}

# Password hashing parameters (PBKDF2-HMAC-SHA256)
PBKDF2_ITERATIONS = 210000
PBKDF2_DKLEN = 32


def hash_password(password, salt):
    """Derive a password hash using PBKDF2-HMAC-SHA256 (slow KDF)."""
    dk = hashlib.pbkdf2_hmac(
        'sha256',
        password.encode('utf-8'),
        salt.encode('utf-8') if isinstance(salt, str) else salt,
        PBKDF2_ITERATIONS,
        dklen=PBKDF2_DKLEN,
    )
    return dk.hex()


def constant_time_compare(val1, val2):
    """Perform constant-time comparison to prevent timing attacks.
    Both values should be of the same type."""
    if isinstance(val1, str):
        val1 = val1.encode('utf-8')
    if isinstance(val2, str):
        val2 = val2.encode('utf-8')
    # Use length of second argument (expected value) to prevent
    # truncation attacks on the comparison
    n = len(val2)
    result = 0
    if len(val1) != n:
        # Lengths differ — not equal, but still iterate to avoid timing leak
        result = 1
        # Pad val1 if shorter to avoid index errors
        if len(val1) < n:
            val1 = val1 + b'\x00' * (n - len(val1))
    for i in range(n):
        result |= val1[i] ^ val2[i]
    return result == 0


def create_token(payload, secret):
    """Create an HMAC-signed token with header.payload.signature format."""
    header = base64.urlsafe_b64encode(json.dumps(
        {'alg': 'HS256', 'typ': 'DOC'}).encode()).rstrip(b'=')
    body = base64.urlsafe_b64encode(json.dumps(payload).encode()).rstrip(b'=')
    signing_input = header + b'.' + body
    signature = hmac.new(
        secret.encode('utf-8') if isinstance(secret, str) else secret,
        signing_input,
        hashlib.sha256
    ).digest()
    sig_encoded = base64.urlsafe_b64encode(signature).rstrip(b'=')
    return (signing_input + b'.' + sig_encoded).decode('utf-8')


def verify_token(token, secret):
    """Verify token signature and return payload if valid."""
    try:
        parts = token.split('.')
        if len(parts) != 3:
            return None

        signing_input = (parts[0] + '.' + parts[1]).encode('utf-8')
        provided_sig = parts[2]

        # Recompute expected signature
        expected_sig_raw = hmac.new(
            secret.encode('utf-8') if isinstance(secret, str) else secret,
            signing_input,
            hashlib.sha256
        ).digest()
        expected_sig = base64.urlsafe_b64encode(expected_sig_raw).rstrip(b'=').decode('utf-8')

        # Constant-time comparison of signatures
        if not constant_time_compare(provided_sig, expected_sig):
            return None

        # Decode payload
        padding = 4 - len(parts[1]) % 4
        if padding != 4:
            parts[1] += '=' * padding
        payload = json.loads(base64.urlsafe_b64decode(parts[1]))

        # Check expiration
        if payload.get('exp', 0) < time.time():
            return None

        return payload
    except Exception:
        return None


def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        auth_header = request.headers.get('Authorization', '')
        if not auth_header.startswith('Bearer '):
            return jsonify({'error': 'Missing authorization'}), 401

        token = auth_header[7:]
        payload = verify_token(token, app.config['SECRET_KEY'])
        if payload is None:
            return jsonify({'error': 'Invalid or expired token'}), 401

        g.user_id = payload.get('sub')
        g.user_role = payload.get('role', 'viewer')
        return f(*args, **kwargs)
    return decorated


def require_role(min_role):
    """Role hierarchy: admin > editor > viewer"""
    role_levels = {'viewer': 0, 'editor': 1, 'admin': 2}
    def decorator(f):
        @wraps(f)
        def decorated(*args, **kwargs):
            user_level = role_levels.get(g.user_role, 0)
            required_level = role_levels.get(min_role, 0)
            if user_level < required_level:
                return jsonify({'error': 'Insufficient permissions'}), 403
            return f(*args, **kwargs)
        return decorated
    return decorator


@app.route('/api/auth/login', methods=['POST'])
def login():
    data = request.get_json()
    if not data or 'username' not in data or 'password' not in data:
        return jsonify({'error': 'Missing credentials'}), 400

    username = data['username']
    user = USERS_DB.get(username)
    if not user:
        return jsonify({'error': 'Invalid credentials'}), 401

    # Verify password using a slow KDF and constant-time comparison
    stored_hash = user['password_hash']
    provided_hash = hash_password(data['password'], user['salt'])

    if not hmac.compare_digest(stored_hash, provided_hash):
        return jsonify({'error': 'Invalid credentials'}), 401

    # Generate token
    payload = {
        'sub': user['id'],
        'role': user['role'],
        'exp': time.time() + 3600,
        'iat': time.time()
    }
    token = create_token(payload, app.config['SECRET_KEY'])
    return jsonify({'token': token, 'expires_in': 3600})


@app.route('/api/documents', methods=['GET'])
@require_auth
def list_documents():
    user_docs = [
        {'id': doc_id, 'title': doc['title'], 'owner': doc['owner_id']}
        for doc_id, doc in DOCUMENTS_DB.items()
        if doc['owner_id'] == g.user_id or g.user_role == 'admin'
    ]
    return jsonify({'documents': user_docs})


@app.route('/api/documents/<doc_id>', methods=['GET'])
@require_auth
def get_document(doc_id):
    doc = DOCUMENTS_DB.get(doc_id)
    if not doc:
        return jsonify({'error': 'Not found'}), 404

    if doc['owner_id'] != g.user_id and g.user_role != 'admin':
        return jsonify({'error': 'Access denied'}), 403

    return jsonify({'document': doc})


@app.route('/api/documents', methods=['POST'])
@require_auth
@require_role('editor')
def create_document():
    data = request.get_json()
    if not data or 'title' not in data or 'content' not in data:
        return jsonify({'error': 'Missing fields'}), 400

    doc_id = secrets.token_hex(16)
    DOCUMENTS_DB[doc_id] = {
        'id': doc_id,
        'title': str(data['title'])[:200],
        'content': str(data['content'])[:10000],
        'owner_id': g.user_id,
        'created_at': time.time()
    }
    return jsonify({'document': DOCUMENTS_DB[doc_id]}), 201


@app.route('/api/documents/<doc_id>', methods=['DELETE'])
@require_auth
@require_role('admin')
def delete_document(doc_id):
    if doc_id in DOCUMENTS_DB:
        del DOCUMENTS_DB[doc_id]
        return jsonify({'status': 'deleted'})
    return jsonify({'error': 'Not found'}), 404


